# Autotune decorator present but launch site bypasses it with static grid
@triton.autotune(configs=[...], key=['xnumel', 'r0_numel'])
@triton.jit
def kernel(in_ptr, out0, out1, xnumel, r0_numel, XBLOCK: tl.constexpr):
    ...

# Static grid hardcodes XBLOCK=128, autotune config selection is ignored
grid = (triton.cdiv(xnumel, 128),)  # always 16 blocks regardless of autotuned XBLOCK
kernel[grid](in_ptr, out0, out1, xnumel, r0_numel)

fast_pseudocode:
# Same autotune decorator, but launch site uses dynamic lambda
@triton.autotune(configs=[...], key=['xnumel', 'r0_numel'])
@triton.jit
def kernel(in_ptr, out0, out1, xnumel, r0_numel, XBLOCK: tl.constexpr):
    ...

# Dynamic grid: autotune-selected XBLOCK drives grid size
grid = lambda meta: (triton.cdiv(xnumel, meta['XBLOCK']),)
kernel[grid](in_ptr, out0, out1, xnumel, r0_numel)  # no XBLOCK kwarg at call site
